package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.view.View;
import android.widget.*;
import org.json.*;
/** Account-backed lists, friend recommendations and notification preferences. */
final class CollectionSheet {
 private final Context c;private final AccountRepository repo;private final NativeSheet sheet;private final String owner;
 private int generation;private boolean saving;private TextView state;
 private interface Rows {void render(JSONArray rows);}
 private CollectionSheet(Context context,String title){c=context;repo=new AccountRepository(c);owner=c.getSharedPreferences("batcaverna",0).getString("user_id","");sheet=new NativeSheet(c,title);sheet.show();}
 static void lists(Context c){new CollectionSheet(c,"Listas").lists();}
 static void recommendations(Context c,String id){new CollectionSheet(c,"Indicações entre amigos").recommendations(id);}
 static void preferences(Context c){new CollectionSheet(c,"Preferências de notificações").preferences();}
 static void add(Context c,String item){new CollectionSheet(c,"Guardar em lista").chooseList(item,"");}
 static void recommend(Context c,String item){new CollectionSheet(c,"Indicar a um amigo").recommendItem(item);}
 static void recommend(Context c,JSONObject item){new CollectionSheet(c,"Indicar a um amigo").friends(item,0);}
 private boolean active(){return sheet.dialog.isShowing()&&owner.equals(c.getSharedPreferences("batcaverna",0).getString("user_id",""));}
 private int reset(String message){generation++;sheet.body.removeAllViews();state=text(message,13);return generation;}
 private TextView text(String value,int size){TextView t=NativeSheet.text(c,value,size,0xffd7cbe7);sheet.body.addView(t);return t;}
 private Button button(String label,Runnable click){Button b=new Button(c);b.setText(label);AppStyle.button(b,false);sheet.body.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(active()&&!saving)click.run();});return b;}
 private JSONObject data(String key,Object value){JSONObject d=new JSONObject();try{d.put(key,value);}catch(JSONException e){throw new IllegalArgumentException(e);}return d;}
 private JSONObject more(JSONObject d,String key,Object value){try{d.put(key,value);}catch(JSONException e){throw new IllegalArgumentException(e);}return d;}
 private void load(String action,JSONObject args,Rows render){int g=reset("Carregando…");repo.features(action,args,(rows,error)->{if(!active()||g!=generation)return;if(error!=null){state.setText(error);button("Tentar novamente",()->load(action,args,render));return;}state.setText("");render.render(rows);});}
 private void save(String action,JSONObject args,Runnable success){if(!active()||saving)return;saving=true;sheet.busy(true);int g=generation;state.setText("Salvando…");repo.features(action,args,(rows,error)->{saving=false;sheet.busy(false);if(!active()||g!=generation)return;if(error!=null){state.setText(error);return;}success.run();});}
 private void lists(){load("lists",new JSONObject(),rows->{text("Listas privadas por padrão. Você pode compartilhá-las com amigos.",13);button("Criar lista",()->name("", ""));if(rows.length()==0)text("Nenhuma lista ainda.",14);for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);String label=r.optString("nome")+" • "+r.optInt("count")+" títulos\n"+(r.optBoolean("mine")?"Sua lista":r.optString("owner_name"))+" • "+(r.optBoolean("compartilhada")?"Amigos":"Privada");button(label,()->list(r));}});}
 private void name(String id,String initial){reset(id.isEmpty()?"Crie uma lista para organizar seus jogos, filmes e séries.":"Renomear lista");EditText input=NativeSheet.input(c,"Nome da lista",60);input.setText(initial);sheet.body.addView(input);button("Salvar",()->{String name=input.getText().toString().trim();if(name.isEmpty()){state.setText("Digite o nome da lista.");return;}save(id.isEmpty()?"create_list":"rename_list",more(data("nome",name),"list_id",id),this::lists);});button("Voltar às listas",this::lists);}
 private void list(JSONObject r){String id=r.optString("id");load("list_items",data("list_id",id),rows->{text(r.optString("nome"),21);boolean mine=r.optBoolean("mine");if(mine){button("Adicionar título da biblioteca",()->pick(id));button(r.optBoolean("compartilhada")?"Tornar privada":"Compartilhar com amigos",()->save("share_list",more(data("list_id",id),"compartilhada",!r.optBoolean("compartilhada")),this::lists));button("Renomear",()->name(id,r.optString("nome")));button("Excluir lista",()->new android.app.AlertDialog.Builder(c).setTitle("Excluir lista?").setMessage("Sua biblioteca permanece intacta.").setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(d,w)->{if(active())save("delete_list",data("list_id",id),this::lists);}).show());}if(rows.length()==0)text("Esta lista ainda está vazia.",14);for(int i=0;i<rows.length();i++){JSONObject item=rows.optJSONObject(i),t=item.optJSONObject("titulo");if(t==null)continue;text(t.optString("nome")+" • "+kind(t),16);if(mine)button("Remover da lista",()->save("remove_item",more(data("list_id",id),"item_id",item.optString("item_id")),()->list(r)));}button("Todas as listas",this::lists);});}
 private static String kind(JSONObject t){return "jogos".equals(t.optString("categoria"))?"Jogo":t.optString("tipo","Filme/Série");}
 private void pick(String list){int g=reset("Carregando sua biblioteca…");repo.profileLibrary((rows,error)->{if(!active()||g!=generation)return;if(error!=null){state.setText(error);return;}state.setText("Busque um jogo, filme ou série da sua biblioteca.");EditText search=NativeSheet.input(c,"Buscar por nome",120);sheet.body.addView(search);LinearLayout results=new LinearLayout(c);results.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(results);Runnable render=()->{results.removeAllViews();String query=search.getText().toString().toLowerCase(java.util.Locale.ROOT);int count=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(!r.optString("nome").toLowerCase(java.util.Locale.ROOT).contains(query))continue;if(++count>100)continue;Button b=new Button(c);b.setText(r.optString("nome")+" • "+kind(r));AppStyle.button(b,false);results.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!active()||saving)return;if(list.isEmpty())friends(r,0);else save("add_item",more(data("list_id",list),"item_id",r.optString("id")),this::lists);});}if(count>100)results.addView(NativeSheet.text(c,"Mostrando 100 títulos. Refine a busca para encontrar outros.",13,0xffb7a5cd));if(count==0)results.addView(NativeSheet.text(c,"Nenhum título encontrado.",13,0xffb7a5cd));};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int n,int x){}public void onTextChanged(CharSequence s,int a,int b,int n){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();button(list.isEmpty()?"Voltar às indicações":"Voltar às listas",()->{if(list.isEmpty())recommendations("");else lists();});});}
 private void chooseList(String item,String rec){load("lists",new JSONObject(),rows->{text("Escolha uma das suas listas.",14);int count=0;for(int i=0;i<rows.length();i++){JSONObject l=rows.optJSONObject(i);if(!l.optBoolean("mine"))continue;count++;button(l.optString("nome"),()->save(rec.isEmpty()?"add_item":"save_recommendation",more(more(data("list_id",l.optString("id")),"item_id",item),"recommendation_id",rec),this::lists));}if(count==0)text("Crie uma lista primeiro e volte a esta ação.",14);button("Criar lista",()->name("",""));});}
 private void recommendItem(String id){int g=reset("Confirmando o título na sua biblioteca…");repo.profileLibrary((rows,error)->{if(!active()||g!=generation)return;if(error!=null){state.setText(error);return;}for(int i=0;i<rows.length();i++){JSONObject item=rows.optJSONObject(i);if(id.equals(item.optString("id"))){friends(item,0);return;}}state.setText("O título não está mais disponível. Atualize a biblioteca e tente novamente.");});}
 private void friends(JSONObject item,int offset){int g=reset("Carregando amigos…");repo.friends(offset,(rows,error)->{if(!active()||g!=generation)return;if(error!=null){state.setText(error);return;}state.setText(rows.length()==0?"Nenhum amigo nesta página.":"Escolha quem receberá a indicação.");for(int i=0;i<rows.length();i++){JSONObject friend=rows.optJSONObject(i);button(friend.optString("nome","Amigo"),()->compose(item,friend));}if(offset>0)button("Anteriores",()->friends(item,Math.max(0,offset-50)));if(rows.length()==50)button("Próximos",()->friends(item,offset+50));button("Voltar às indicações",()->recommendations(""));});}
 private void compose(JSONObject item,JSONObject friend){reset("Indicar para "+friend.optString("nome","Amigo"));EditText message=NativeSheet.input(c,"Por que recomenda? (opcional)",240);message.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);message.setMinLines(3);sheet.body.addView(message);button("Enviar indicação",()->{try{JSONObject payload=RecommendationInput.payload(item,friend.optString("id"),message.getText().toString());save("recommend",payload,()->{Toast.makeText(c,"Indicação enviada",Toast.LENGTH_SHORT).show();recommendations("");});}catch(JSONException e){state.setText("Atualize a biblioteca e escolha o título novamente.");}});button("Escolher outro amigo",()->friends(item,0));}
 private void recommendations(String target){load("recommendations",target.isEmpty()?new JSONObject():data("id",target),rows->{text("Aceite uma indicação para revisar e adicionar o título à sua biblioteca.",13);button("Indicar título",()->pick(""));button("Atualizar / ver todas",()->recommendations(""));if(rows.length()==0)text("Nenhuma indicação disponível.",14);for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i),t=r.optJSONObject("titulo");if(t==null)continue;String id=r.optString("id");text(t.optString("nome")+" • "+kind(t),20);text((r.optBoolean("received")?"De "+r.optString("sender_name"):"Para "+r.optString("recipient_name"))+" • "+r.optString("estado"),13);if(!r.optString("mensagem").isEmpty())text(r.optString("mensagem"),15);if(r.optBoolean("received")){button("Aceitar e adicionar",()->{try{JSONObject draft=RecommendationInput.draft(t);int ticket=generation;new CatalogAddDialog(c,!"jogos".equals(draft.optString("categoria")),RecommendationInput.type(draft),draft,()->{if(active()&&ticket==generation)save("recommendation_state",more(data("id",id),"estado","interesse"),()->recommendations(target));});}catch(Exception e){state.setText("Não foi possível abrir o título: "+e.getMessage());}});button("Guardar em lista",()->chooseList("",id));button("Dispensar",()->save("recommendation_state",more(data("id",id),"estado","dispensada"),()->recommendations(target)));}}});}
 private void preferences(){load("preferences",new JSONObject(),rows->{text("Salvas na conta e usadas no site e no APK para novas notificações. As antigas permanecem na central. Mensagens e publicações continuam disponíveis.",13);String[] keys={"mensagens","social","amizades","indicacoes","progresso"},labels={"Mensagens privadas e grupos","Publicações, curtidas e comentários","Amizades e convites de grupos","Indicações de amigos","Missões, conquistas e níveis"};JSONObject p=rows.optJSONObject(0);Switch[] toggles=new Switch[keys.length];for(int i=0;i<keys.length;i++){Switch s=new Switch(c);s.setText(labels[i]);s.setTextColor(0xffded2eb);s.setPadding(0,NativeSheet.dp(c,12),0,NativeSheet.dp(c,12));s.setChecked(p==null||p.optBoolean(keys[i],true));sheet.body.addView(s);toggles[i]=s;}button("Salvar na conta",()->{JSONObject d=new JSONObject();for(int i=0;i<keys.length;i++)more(d,keys[i],toggles[i].isChecked());save("save_preferences",d,()->{Toast.makeText(c,"Preferências salvas na conta",Toast.LENGTH_SHORT).show();preferences();});});});}
}
